// One axial head slice (T1-weighted and T2-weighted MRI of the same head), shared by the registration chapters.
// 128 x 128, row-major (x = row, down; y = column, right). Intensities scaled so the 99.9th percentile of the head is 1.
// brain: 1 inside the brain mask. tissue: 0 other, 1 CSF, 2 gray matter, 3 white matter, 4 deep gray matter.
window.HEAD = (() => {
  const dec = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
  const n = 128, f = (u) => Float32Array.from(u, (v) => v / 255);
  return { n, t1: f(dec("")), t2: f(dec("")), brain: dec(""), tissue: dec("") };
})();
